contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "n", "s"); }

    function testFuzz_property(address caller, uint256 amt) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        uint256 mintAmount = bound(amt, 1, type(uint256).max / 2);
        c.mintToken(caller, mintAmount);

        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(caller);

        vm.prank(caller);
        bool ok;
        try c.burn(mintAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
